class Solution { public String decodeCiphertext(String encodedText,int rows){int cols=encodedText.length()/rows;StringBuilder answer=new StringBuilder();for(int start=0;start<cols;start++)for(int row=0,col=start;row<rows&&col<cols;row++,col++)answer.append(encodedText.charAt(row*cols+col));while(answer.length()>0&&answer.charAt(answer.length()-1)==' ')answer.deleteCharAt(answer.length()-1);return answer.toString();} }
